before.content:
@import "tailwindcss";

:root {
  font-family: Inter, ui-sans-serif, system-ui, sans-serif;
  color: #172033;
  background: #f6f7f9;
  font-synthesis: none;
}
* { box-sizing: border-box; }
body { margin: 0; min-width: 320px; }
button, textarea { font: inherit; }
button { cursor: pointer; }
button:focus-visible, textarea:focus-visible { outline: 3px solid #99b6ff; outline-offset: 2px; }
button:disabled { opacity: .5; cursor: not-allowed; }
.primary { color: #fff; background: #315fd6; border-color: #315fd6; }
.eyebrow { margin: 0 0 .25rem; color: #53627b; font-size: .75rem; letter-spacing: .1em; text-transform: uppercase; }
.welcome { min-height: 100vh; display: grid; place-items: center; padding: 2rem; background: radial-gradient(circle at 20% 20%, #e9efff, transparent 45%), #f8f9fb; }
.welcome > div { max-width: 32rem; }
.welcome h1 { font-size: clamp(2rem, 7vw, 4rem); line-height: 1; margin: .4rem 0 1rem; }
.shell { min-height: 100vh; display: grid; grid-template-columns: 15rem minmax(0, 1fr); }
aside { padding: 1.5rem 1.1rem; background: #0d1729; color: #dbe4f7; display: flex; flex-direction: column; justify-content: space-between; }
.logo { display: inline-grid; place-items: center; width: 2.3rem; height: 2.3rem; border-radius: .7rem; background: #3159b8; color: white; font-weight: 800; }
aside nav { display: grid; gap: .3rem; }
aside nav > * { color: #9eabc0; padding: .65rem .75rem; border-radius: .6rem; }
aside nav [aria-current="page"] { color: white; background: #182640; }
.chat { min-width: 0; height: 100vh; display: grid; grid-template-rows: auto minmax(0, 1fr) auto; }
.chat > header { padding: 1.15rem clamp(1rem, 4vw, 3rem); display: flex; justify-content: space-between; align-items: center; border-bottom: 1px solid #e2e5eb; background: rgba(255,255,255,.78); backdrop-filter: blur(12px); }
.chat h1 { margin: 0; font-size: 1.25rem; }
.online { color: #246844; font-size: .8rem; }
.timeline { overflow: auto; padding: 2rem clamp(1rem, 8vw, 8rem); display: flex; flex-direction: column; gap: 1.2rem; }
.message { max-width: 46rem; width: 100%; }
.message.user { align-self: flex-end; max-width: 34rem; }
.message-content { padding: .9rem 1rem; border-radius: 1rem; background: white; box-shadow: 0 10px 34px rgba(32,43,67,.05); }

after.content:
.tool-details { margin-top: .4rem; color: #526079; font-family: ui-monospace, monospace; font-size: .78rem; overflow-wrap: anywhere; }
.tool-details pre { margin: .25rem 0 .6rem; white-space: pre-wrap; }
.composer-wrap { padding: .6rem clamp(1rem, 8vw, 8rem) 1.3rem; background: linear-gradient(transparent, #f6f7f9 25%); }
.config { max-width: 52rem; margin: 0 auto .45rem; display: flex; gap: .45rem; flex-wrap: wrap; align-items: center; color: #5e6b80; font-size: .72rem; }
.config > span { background: #e8ebf1; border-radius: 99px; padding: .4rem .65rem; }
.prompt-input { max-width: 52rem; margin: auto; padding: .75rem; border: 1px solid #cfd5df; border-radius: 1rem; background: white; box-shadow: 0 16px 42px rgba(32,43,67,.09); }
.prompt-textarea { width: 100%; resize: none; border: 0; outline: none; padding: .25rem; color: inherit; background: transparent; }
.composer-actions { display: flex; justify-content: space-between; align-items: center; color: #647086; font-size: .8rem; }
.queue { max-width: 52rem; margin: 0 auto .6rem; padding: .65rem; border-radius: .8rem; background: #e9edf5; }
.queue > div:first-child, .queue-item { display: flex; justify-content: space-between; align-items: center; gap: .7rem; }
.queue-item { padding-top: .35rem; }
.queue-item > span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.error { color: #8d2e2e; background: #fff0f0; border-radius: .6rem; padding: .75rem; }
.dialog-overlay, .sheet-overlay { position: fixed; inset: 0; background: rgba(8,14,26,.62); z-index: 40; }
.dialog-content { position: fixed; top: 50%; left: 50%; transform: translate(-50%,-50%); width: min(30rem, calc(100vw - 2rem)); padding: 1.4rem; border-radius: 1rem; background: white; box-shadow: 0 24px 90px rgba(0,0,0,.28); z-index: 50; }
.dialog-content h2 { margin-top: 0; }
.dialog-content code { overflow-wrap: anywhere; }
.dialog-actions { display: flex; justify-content: flex-end; gap: .6rem; margin-top: 1.2rem; }
.sheet-content { position: fixed; inset: 0 auto 0 0; width: min(19rem, 88vw); padding: 1rem; background: #0d1729; color: #dbe4f7; z-index: 50; box-shadow: 20px 0 60px rgba(0,0,0,.3); }
.sheet-content > h2, .sheet-content > p { margin-left: .8rem; }
.select-trigger { min-height: 2rem; display: inline-flex; gap: .35rem; align-items: center; padding: .3rem .55rem; border: 0; border-radius: 99px; color: inherit; background: #e8ebf1; }
.select-content { min-width: 10rem; padding: .25rem; border: 1px solid #cfd5df; border-radius: .6rem; background: white; box-shadow: 0 12px 35px rgba(0,0,0,.18); z-index: 60; }
.select-item { display: flex; justify-content: space-between; gap: .8rem; padding: .45rem .6rem; border-radius: .4rem; outline: 0; }
.select-item[data-highlighted] { background: #e7edff; }
.page { min-height: 100vh; }
.page > :not(header) { margin: 2rem clamp(1rem, 5vw, 4rem); }
.empty-page { min-height: 100vh; display: grid; align-content: center; justify-content: center; padding: 2rem; }
.empty-page > * { max-width: 34rem; }
.search-form { display: grid; gap: .5rem; max-width: 48rem; }
.search-form > div { display: flex; gap: .5rem; }
.search-form input { flex: 1; min-width: 0; padding: .7rem; border: 1px solid #b9c1cf; border-radius: .55rem; }
.result-list { display: grid; gap: .65rem; max-width: 52rem; }
.result-list a { display: grid; gap: .25rem; padding: .9rem 1rem; border-radius: .7rem; background: white; }
.result-list span { color: #5c687b; }
[role="tablist"] { display: flex; flex-wrap: wrap; gap: .35rem; }
[role="tab"] { padding: .5rem .7rem; border: 0; border-radius: .5rem; background: #e8ebf1; }
[role="tab"][data-state="active"] { color: white; background: #315fd6; }
.settings-section { max-width: 48rem; }
.warning { padding: .75rem; border-left: 3px solid #b47700; background: #fff4c7; }
@media (max-width: 720px) {
  .app-shell { display: block; }
  .sidebar { display: none; }
  .mobile-bar { height: 3.5rem; padding: .5rem .75rem; display: flex; justify-content: space-between; align-items: center; background: #0d1729; color: white; }
  .mobile-bar .logo { width: 2rem; height: 2rem; }
  .mobile-nav { padding: .5rem 0; min-height: auto; }
  .chat-page { height: calc(100dvh - 3.5rem); }
  .chat-page > header { padding: .9rem 1rem; }
  .timeline { padding: 1rem; }
  .composer-wrap { padding: .5rem .7rem max(.7rem, env(safe-area-inset-bottom)); }
  .message.user { max-width: 92%; }
  .queue { max-height: 8rem; overflow: auto; }
  .page { min-height: calc(100vh - 3.5rem); }
}
@media (prefers-color-scheme: dark) {
  :root { color: #e7ecf5; background: #0b1220; }
  .workspace, .chat-page, .welcome, .page { background: #0b1220; }
  .chat-page > header, .page > header { background: rgba(11,18,32,.8); border-color: #263249; }
  .message-content, .prompt-input, .dialog-content, .select-content, .result-list a { background: #162137; border-color: #35415a; }
  .message.user .message-content { background: #233557; }
  .tool, .config > span, .select-trigger, .queue, [role="tab"] { background: #18263e; }
  .composer-wrap { background: linear-gradient(transparent, #0b1220 25%); }
  .prompt-textarea, input { color: #e7ecf5; background: #101a2c; }
  button { background: #1a2841; color: #e7ecf5; border-color: #41506b; }
  .primary, [role="tab"][data-state="active"] { background: #5782ef; }
  .select-item[data-highlighted] { background: #233557; }
  .warning, .system-banner { color: #ffe7a3; background: #3b2e0b; }
}
@media (forced-colors: active) { .online span, .warning, .error { forced-color-adjust: auto; } }
